-- ================================================
-- Seed Copa do Mundo 2026 — Grupos Oficiais + Mata-Mata
-- 72 jogos na fase de grupos + 32 no mata-mata
-- Times reais baseados no sorteio oficial
-- Horários em UTC (equivalente Brasília = UTC-3)
-- ================================================

DELETE FROM public.jogos WHERE time_a LIKE '%1%' AND fase = 'grupos' AND grupo IS NULL;

ON CONFLICT (id) DO NOTHING;
